  --primary-foreground: #0a0c10;
  --secondary: #171b23;
  --secondary-foreground: #e6e9ef;
  --muted: #11141b;
  --muted-foreground: #8b94a5;
  --accent: #14213d;
  --accent-foreground: #93c5fd;
  --border: #1f2430;
  --input: #272d3a;
  --ring: #3b82f6;
  --destructive: #f43f5e;
  --success: #10b981;
  --warning: #f59e0b;
  --info: #60a5fa;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-destructive: var(--destructive);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --radius-sm: calc(var(--radius) - 2px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);
  --font-sans: 'Inter', ui-sans-serif, system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', ui-monospace, monospace;
  --animate-in: fade-in 0.15s ease-out;
  --animate-pop: pop 0.15s ease-out;
  --animate-slide-right: slide-right 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-slide-left: slide-left 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-shimmer: shimmer 1.6s linear infinite;
  --animate-stream-in: stream-in 0.45s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-wave: wave 1.1s ease-in-out infinite;
  --animate-toast: toast 0.25s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-marquee: marquee 30s linear infinite;
  --animate-beam: beam 4s linear infinite;
  --animate-flip: flip 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-spin-in: spin-in 0.5s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-shake: shake 0.4s cubic-bezier(0.36, 0.07, 0.19, 0.97);
  --animate-slide-up: slide-up 0.28s cubic-bezier(0.22, 1, 0.36, 1);
  --animate-loader-bars: loader-bars 1s ease-in-out infinite;
  --animate-loader-dots: loader-dots 1.2s ease-in-out infinite;
  --animate-loader-bar: loader-bar 1.4s cubic-bezier(0.65, 0, 0.35, 1) infinite;
  --animate-loader-ring: loader-ring 1.4s ease-out infinite;
}

@property --beam-angle { syntax: '<angle>'; initial-value: 0deg; inherits: false; }

