/* Per-stroke icon motion (see SPEC in icons.tsx): each moving stroke carries --ic (the keyframes) and its numbers; the icon or a .group parent being hovered plays them. */
.icon-special [data-ic] { transform-box: view-box; transform-origin: var(--o, 12px 12px); }
.icon-special:hover [data-ic], .group:hover .icon-special [data-ic], .icon-once [data-ic] { animation: var(--ic) var(--icon-ms, 0.8s) var(--ie, cubic-bezier(0.34, 1.3, 0.64, 1)) var(--w, 0s) both; }
.icon-loop [data-ic] { animation: var(--ic) 1.6s ease-in-out var(--w, 0s) infinite !important; }
.icon-once:not(:hover) [data-ic] { animation-iteration-count: 1; }
