@keyframes ic-orbit { 0%, 100% { transform: translate(0, 0) } 25% { transform: translate(var(--d), 0) } 50% { transform: translate(0, var(--d)) } 75% { transform: translate(calc(var(--d) * -1), 0) } }
@keyframes ic-peek { 0%, 100% { transform: translate(0, 0); opacity: 1 } 40% { transform: translate(var(--dx), var(--dy)); opacity: 0 } 41% { transform: translate(calc(var(--dx) * -1), calc(var(--dy) * -1)); opacity: 0 } }
