@keyframes ic-ping { 0%, 100% { transform: scale(1); opacity: 1 } 40% { transform: scale(var(--s)); opacity: 0.35 } }
@keyframes ic-stretch { 0%, 100% { transform: scaleX(1) } 40% { transform: scaleX(var(--s)) } 70% { transform: scaleX(0.94) } }
